"% Steady level-flight trim for transport aircraft

% Given parameters
W = 280000.0;      % lbf
S = 2730.0;        % ft^2
h = 35000.0;       % ft
V = 780.0;         % ft/s

% Lift coefficients
CL0 = 0.18;
CLalpha = 5.6;     % /rad

% Drag polar
CD0 = 0.019;
k = 0.045;

% Atmosphere
rho0 = 0.0023769;  % slug/ft^3
scale_height = 23800; % ft

% Engine model
T0 = 68000.0;      % lbf
V0 = 780.0;        % ft/s
exponent = 0.8;

% Calculate air density using exponential atmosphere
rho = rho0 * exp(-h / scale_height);

% Calculate dynamic pressure
qbar = 0.5 * rho * V^2;

% Steady level-flight condition: Lift = Weight
% L = qbar * S * CL = W
% CL = CL0 + CLalpha * alpha
CL_required = W / (qbar * S);

% Solve for angle of attack (alpha in radians)
alpha_rad = (CL_required - CL0) / CLalpha;

% Convert to degrees
alpha_deg = alpha_rad * 180 / pi;

% Calculate drag coefficient from parabolic drag polar
CD = CD0 + k * CL_required^2;

% Steady level-flight condition: Drag = Thrust
% D = qbar * S * CD = T
thrust_lbf = qbar * S * CD;

% Create result struct with required keys
result = struct();
result.alpha_trim_deg = alpha_deg;
result.thrust_lbf = thrust_lbf;

% Write result to JSON file
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonStr);
fclose(fid);"
